const express = require('express');
const { NotFoundError, ValidationError, DatabaseError } = require('./errors');
const app = express();

// Centralized error handling middleware
app.use((err, req, res, next) => {
  // Set default status and message
  const status = err.status || 500;
  const message = err.message || 'Internal Server Error';

  // Log the error (in production, you might want to use a logging library)
  console.error(`${status} - ${message} - ${req.originalUrl} - ${req.method} - ${req.ip}`);

  // Send response
  res.status(status).json({
    error: {
      message: message,
      name: err.name,
    }
  });
});

app.get('/health', (req, res, next) => {
  try {
    // Simulate potential error
    if (Math.random() < 0.1) { // 10% chance of database error
      throw new DatabaseError('Failed to connect to health check database');
    }

    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (err) {
    next(err);
  }
});

app.get('/users', (req, res, next) => {
  try {
    // Simulate potential error
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    if (users.length === 0) {
      throw new NotFoundError('No users found');
    }

    res.json(users);
  } catch (err) {
    next(err);
  }
});

app.get('/users/:id', (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    if (isNaN(userId)) {
      throw new ValidationError('User ID must be a number');
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      throw new NotFoundError(`User with ID ${userId} not found`);
    }

    res.json(user);
  } catch (err) {
    next(err);
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

