const express = require('express');
const { NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

// Middleware to parse JSON bodies
app.use(express.json());

// Health check route
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users route
app.get('/users', (req, res, next) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    if (users.length === 0) {
      throw new NotFoundError('No users found');
    }

    res.json(users);
  } catch (error) {
    next(error);
  }
});

// Add a route that might have validation errors
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body;

    if (!name || !email) {
      throw new ValidationError('Name and email are required');
    }

    // Simulate database operation
    if (Math.random() < 0.1) { // 10% chance of database error
      throw new DatabaseError('Failed to save user to database');
    }

    const newUser = {
      id: Math.floor(Math.random() * 1000),
      name,
      email
    };

    res.status(201).json(newUser);
  } catch (error) {
    next(error);
  }
});

// Catch 404 for undefined routes
app.use('*', (req, res, next) => {
  next(new NotFoundError(`Can't find ${req.originalUrl} on this server!`));
});

// Global error handling middleware
app.use((error, req, res, next) => {
  // Set defaults
  error.statusCode = error.statusCode || 500;
  error.status = error.status || 'error';

  // Send error response
  res.status(error.statusCode).json({
    status: error.status,
    message: error.message,
    // Only add stack trace in development
    ...(process.env.NODE_ENV === 'development' && { stack: error.stack })
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

